@strawberry.type
class EmployeeType:
    id: int
    full_name: str
    department: str

    @strawberry.field
    async def compensation_grade(self, info: Info) -> Optional[CompensationGradeType]:
        user = info.context.get("current_user")
        if not user or (user.id != self.id and user.role not in ["HR_ADMIN", "EXECUTIVE"]):
            return None

        loader: DataLoader = info.context["compensation_loader"]
        band = await loader.load(self.id)
        if not band:
            return None
        return CompensationGradeType(grade_tier=band.tier_code, base_midpoint=band.base_midpoint)
